# Let's also verify the HTML has no unclosed tags
from html.parser import HTMLParser

class TagChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.self_closing = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 
                            'link', 'meta', 'param', 'source', 'track', 'wbr', 'canvas'}
        self.issues = []

    def handle_starttag(self, tag, attrs):
        if tag not in self.self_closing:
            self.stack.append(tag)

    def handle_endtag(self, tag):
        if tag in self.self_closing:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.issues.append(f"Unexpected closing tag: </{tag}>")

with open('output/final_report.html', 'r') as f:
    html = f.read()

checker = TagChecker()
try:
    checker.feed(html)
    if checker.stack:
        print("Unclosed tags:", checker.stack)
    else:
        print("All tags properly closed")
    if checker.issues:
        print("Issues:", checker.issues)
    else:
        print("No tag mismatch issues")
except Exception as e:
    print(f"Parse error: {e}")
